1	"use client";
2	import { useCallback, useEffect, useMemo, useState } from "react";
3	
4	type Master = { id: string; name: string };
5	type Service = { id: string; name: string; durationMin: number; priceKzt: number; staff: Master[] };
6	type Slot = { startMs: number; endMs: number };
7	type Hold = { holdToken: string; expiresInSec: number; slot: Slot };
8	
9	const fmtPrice = (kzt: number) => `${kzt.toLocaleString("en-GB")} ₸`;
10	
11	/** Offered instead of an empty slot grid: a full day is a lead, not a dead end. */
12	function WaitlistBox({
13	  slug,
14	  serviceId,
15	  staffId,
16	  date,
17	}: {
18	  slug: string;
19	  serviceId: string;
20	  staffId: string;
21	  date: string;
22	}) {
23	  const [name, setName] = useState("");
24	  const [phone, setPhone] = useState("");
25	  const [state, setState] = useState<"idle" | "sending" | "joined" | "error">("idle");
26	
27	  if (state === "joined") {
28	    return (
29	      <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">
30	        You are on the waitlist for {date}. The moment a slot frees up we message you first — you get
31	        15 minutes to claim it.
32	      </div>
33	    );
34	  }
35	
36	  async function submit() {
37	    setState("sending");
38	    const res = await fetch(`/api/public/${slug}/waitlist`, {
39	      method: "POST",
40	      headers: { "content-type": "application/json" },
41	      body: JSON.stringify({ serviceId, staffId, date, name, phone }),
42	    });
43	    setState(res.ok ? "joined" : "error");
44	  }
45	
46	  return (
47	    <div className="rounded-xl border border-zinc-200 bg-white p-4">
48	      <p className="text-sm text-zinc-700">
49	        This day is fully booked. Join the waitlist — if someone cancels, the slot is offered
50	        to you.
51	      </p>
52	      <div className="mt-3 space-y-2">
53	        <input
54	          placeholder="Name"
55	          value={name}
56	          onChange={(e) => setName(e.target.value)}
57	          className="w-full rounded-lg border border-zinc-300 px-3 py-2"
58	        />
59	        <input
60	          placeholder="+7701…"
61	          type="tel"
62	          value={phone}
63	          onChange={(e) => setPhone(e.target.value)}
64	          className="w-full rounded-lg border border-zinc-300 px-3 py-2"
65	        />
66	        <button
67	          onClick={submit}
68	          disabled={state === "sending" || !name.trim() || !phone.trim()}
69	          className="w-full rounded-lg border border-zinc-900 px-4 py-2 text-zinc-900 disabled:opacity-50"
70	        >
71	          {state === "sending" ? "Joining…" : "Join the waitlist"}
72	        </button>
73	        {state === "error" && (
74	          <p className="text-sm text-red-600">That did not work — check the phone number and try again</p>
75	        )}
76	      </div>
77	    </div>
78	  );
79	}
80	
81	export function BookingWizard({ slug, timezone }: { slug: string; timezone: string }) {
82	  const [services, setServices] = useState<Service[] | null>(null);
83	  const [service, setService] = useState<Service | null>(null);
84	  const [master, setMaster] = useState<Master | null>(null);
85	  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
86	  const [slots, setSlots] = useState<Slot[] | null>(null);
87	  const [hold, setHold] = useState<Hold | null>(null);
88	  const [holdLeft, setHoldLeft] = useState(0);
89	  const [name, setName] = useState("");
90	  const [phone, setPhone] = useState("");
91	  const [error, setError] = useState<string | null>(null);
92	  const [done, setDone] = useState(false);
93	  const [busy, setBusy] = useState(false);
94	
95	  const fmtTime = useMemo(
96	    () =>
97	      new Intl.DateTimeFormat("en-GB", { hour: "2-digit", minute: "2-digit", timeZone: timezone }),
98	    [timezone],
99	  );
100	
101	  useEffect(() => {
102	    fetch(`/api/public/${slug}/catalog`)
103	      .then((r) => r.json())
104	      .then((d) => setServices(d.services ?? []))
105	      .catch(() => setError("Could not load services"));
106	  }, [slug]);
107	
108	  // Data lands asynchronously; loading state is `slots === null`,
109	  // reset in the event handlers that change service/master/date.
110	  const loadSlots = useCallback(() => {
111	    if (!service || !master) return;
112	    fetch(`/api/public/${slug}/slots?serviceId=${service.id}&staffId=${master.id}&date=${date}`)
113	      .then((r) => r.json())
114	      .then((d) => setSlots(d.slots ?? []))
115	      .catch(() => setError("Could not load available times"));
116	  }, [slug, service, master, date]);
117	
118	  useEffect(loadSlots, [loadSlots]);
119	
120	  // Hold countdown (initial value is set in pickSlot)
121	  useEffect(() => {
122	    if (!hold) return;
123	    const t = setInterval(() => setHoldLeft((s) => Math.max(0, s - 1)), 1000);
124	    return () => clearInterval(t);
125	  }, [hold]);
126	
127	  async function pickSlot(slot: Slot) {
128	    if (!service || !master) return;
129	    setBusy(true);
130	    setError(null);
131	    const res = await fetch(`/api/public/${slug}/hold`, {
132	      method: "POST",
133	      headers: { "content-type": "application/json" },
134	      body: JSON.stringify({ serviceId: service.id, staffId: master.id, date, startMs: slot.startMs }),
135	    });
136	    setBusy(false);
137	    if (!res.ok) {
138	      setError("That time was just taken — pick another one");
139	      loadSlots();
140	      return;
141	    }
142	    const h: Hold = await res.json();
143	    setHold(h);
144	    setHoldLeft(h.expiresInSec);
145	  }
146	
147	  async function confirm() {
148	    if (!service || !master || !hold) return;
149	    setBusy(true);
150	    setError(null);
151	    const res = await fetch(`/api/public/${slug}/book`, {
152	      method: "POST",
153	      headers: { "content-type": "application/json" },
154	      body: JSON.stringify({
155	        serviceId: service.id,
156	        staffId: master.id,
157	        startMs: hold.slot.startMs,
158	        endMs: hold.slot.endMs,
159	        holdToken: hold.holdToken,
160	        name,
161	        phone,
162	      }),
163	    });
164	    setBusy(false);
165	    if (!res.ok) {
166	      const d = await res.json().catch(() => ({}));
167	      setError(
168	        d.error === "hold_expired"
169	          ? "The hold expired — pick a time again"
170	          : d.error === "bad_request"
171	            ? "Check the name and phone (format +7701…)"
172	            : "That time is already taken — pick another one",
173	      );
174	      if (d.error !== "bad_request") {
175	        setHold(null);
176	        loadSlots();
177	      }
178	      return;
179	    }
180	    setDone(true);
181	  }
182	
183	  if (done && service && master && hold) {
184	    return (
185	      <div className="rounded-2xl border border-emerald-200 bg-emerald-50 p-6 text-center">
186	        <div className="text-4xl">✅</div>
187	        <h2 className="mt-2 text-xl font-semibold text-emerald-900">You are booked!</h2>
188	        <p className="mt-2 text-emerald-800">
189	          {service.name} · {master.name}
190	          <br />
191	          {new Intl.DateTimeFormat("en-GB", { dateStyle: "long", timeZone: timezone }).format(hold.slot.startMs)}{" "}
192	          at {fmtTime.format(hold.slot.startMs)}
193	        </p>
194	        <button
195	          onClick={() => location.reload()}
196	          className="mt-4 rounded-lg bg-emerald-700 px-4 py-2 text-sm text-white"
197	        >
198	          Book again
199	        </button>
200	      </div>
201	    );
202	  }
203	
204	  return (
205	    <div className="space-y-6">
206	      {/* Step 1: service */}
207	      <section>
208	        <h2 className="mb-2 font-semibold text-zinc-800">1 · Service</h2>
209	        {!services ? (
210	          <p className="text-sm text-zinc-400">Loading…</p>
211	        ) : (
212	          <div className="grid gap-2">
213	            {services.map((svc) => (
214	              <button
215	                key={svc.id}
216	                onClick={() => {
217	                  setService(svc);
218	                  setMaster(null);
219	                  setHold(null);
220	                  setSlots(null);
221	                }}
222	                className={`flex items-center justify-between gap-3 rounded-xl border px-4 py-3 text-left transition ${
223	                  service?.id === svc.id
224	                    ? "border-zinc-900 bg-zinc-900 text-white"
225	                    : "border-zinc-200 bg-white hover:border-zinc-400"
226	                }`}
227	              >
228	                <span>
229	                  {svc.name}
230	                  <span className={service?.id === svc.id ? "text-zinc-300" : "text-zinc-400"}>
231	                    {" "}
232	                    · {svc.durationMin} min
233	                  </span>
234	                </span>
235	                <span className="shrink-0 font-medium">{fmtPrice(svc.priceKzt)}</span>
236	              </button>
237	            ))}
238	          </div>
239	        )}
240	      </section>
241	
242	      {/* Step 2: master */}
243	      {service && (
244	        <section>
245	          <h2 className="mb-2 font-semibold text-zinc-800">2 · Staff member</h2>
246	          <div className="flex flex-wrap gap-2">
247	            {service.staff.map((m) => (
248	              <button
249	                key={m.id}
250	                onClick={() => {
251	                  setMaster(m);
252	                  setHold(null);
253	                  setSlots(null);
254	                }}
255	                className={`rounded-full border px-4 py-2 transition ${
256	                  master?.id === m.id
257	                    ? "border-zinc-900 bg-zinc-900 text-white"
258	                    : "border-zinc-200 bg-white hover:border-zinc-400"
259	                }`}
260	              >
261	                {m.name}
262	              </button>
263	            ))}
264	          </div>
265	        </section>
266	      )}
267	
268	      {/* Step 3: date + slot */}
269	      {service && master && !hold && (
270	        <section>
271	          <h2 className="mb-2 font-semibold text-zinc-800">3 · Date and time</h2>
272	          <input
273	            type="date"
274	            value={date}
275	            min={new Date().toISOString().slice(0, 10)}
276	            onChange={(e) => {
277	              setDate(e.target.value);
278	              setSlots(null);
279	            }}
280	            className="mb-3 rounded-lg border border-zinc-300 px-3 py-2"
281	          />
282	          {!slots ? (
283	            <p className="text-sm text-zinc-400">Loading…</p>
284	          ) : slots.length === 0 ? (
285	            <WaitlistBox
286	              slug={slug}
287	              serviceId={service.id}
288	              staffId={master.id}
289	              date={date}
290	            />
291	          ) : (
292	            <div className="grid grid-cols-4 gap-2 sm:grid-cols-5">
293	              {slots.map((slot) => (
294	                <button
295	                  key={slot.startMs}
296	                  disabled={busy}
297	                  onClick={() => pickSlot(slot)}
298	                  className="rounded-lg border border-zinc-200 bg-white px-2 py-2 text-sm transition hover:border-zinc-900 disabled:opacity-50"
299	                >
300	                  {fmtTime.format(slot.startMs)}
301	                </button>
302	              ))}
303	            </div>
304	          )}
305	        </section>
306	      )}
307	
308	      {/* Step 4: contacts */}
309	      {hold && (
310	        <section className="rounded-2xl border border-zinc-200 bg-white p-4">
311	          <h2 className="font-semibold text-zinc-800">4 · Your details</h2>
312	          <p className="mt-1 text-sm text-zinc-500">
313	            Slot {fmtTime.format(hold.slot.startMs)} held for another{" "}
314	            <span className={holdLeft < 60 ? "font-semibold text-red-600" : "font-semibold"}>
315	              {Math.floor(holdLeft / 60)}:{String(holdLeft % 60).padStart(2, "0")}
316	            </span>
317	          </p>
318	          <div className="mt-3 space-y-3">
319	            <input
320	              placeholder="Name"
321	              value={name}
322	              onChange={(e) => setName(e.target.value)}
323	              className="w-full rounded-lg border border-zinc-300 px-3 py-2"
324	            />
325	            <input
326	              placeholder="+7701…"
327	              type="tel"
328	              value={phone}
329	              onChange={(e) => setPhone(e.target.value)}
330	              className="w-full rounded-lg border border-zinc-300 px-3 py-2"
331	            />
332	            <div className="flex gap-2">
333	              <button
334	                onClick={confirm}
335	                disabled={busy || !name.trim() || !phone.trim() || holdLeft === 0}
336	                className="flex-1 rounded-lg bg-zinc-900 px-4 py-2 text-white disabled:opacity-50"
337	              >
338	                {busy ? "Confirming…" : "Confirm booking"}
339	              </button>
340	              <button
341	                onClick={() => {
342	                  setHold(null);
343	                  loadSlots();
344	                }}
345	                className="rounded-lg border border-zinc-300 px-4 py-2"
346	              >
347	                Back
348	              </button>
349	            </div>
350	          </div>
351	        </section>
352	      )}
353	
354	      {error && <p className="text-sm text-red-600">{error}</p>}
355	    </div>
356	  );
357	}
