1	import "server-only";
2	import { randomBytes } from "node:crypto";
3	import { and, eq, gte, inArray, lt } from "drizzle-orm";
4	import { db, schema as s } from "@/db";
5	import { cancelByDedupeKey, enqueue } from "./outbox";
6	import { redis } from "./redis";
7	import { localTimeToUtc, isoWeekday, slotsForDay, type Range } from "./slots";
8	
9	// ---------- Redis slot holds (first line of defense against double-booking) ----------
10	
11	const holdKey = (staffId: string, startMs: number) => `hold:${staffId}:${startMs}`;
12	
13	export type Hold = { token: string; endMs: number };
14	
15	/** Try to place a hold on a slot. Returns a token, or null if already held. */
16	export async function createHold(
17	  staffId: string,
18	  slot: Range,
19	  ttlSec: number,
20	): Promise<string | null> {
21	  const token = randomBytes(16).toString("hex");
22	  const ok = await redis().set(
23	    holdKey(staffId, slot.startMs),
24	    JSON.stringify({ token, endMs: slot.endMs } satisfies Hold),
25	    "EX",
26	    ttlSec,
27	    "NX",
28	  );
29	  return ok ? token : null;
30	}
31	
32	/** Active holds for a master within [fromMs, toMs). */
33	// ponytail: KEYS-scan per request is O(active holds); holds expire in minutes,
34	// so the set stays tiny. Move to a per-staff zset if a business ever needs it.
35	export async function listHolds(staffId: string, fromMs: number, toMs: number): Promise<Range[]> {
36	  const keys = await redis().keys(`hold:${staffId}:*`);
37	  if (keys.length === 0) return [];
38	  const values = await redis().mget(keys);
39	  const out: Range[] = [];
40	  keys.forEach((k, i) => {
41	    const raw = values[i];
42	    if (!raw) return;
43	    const startMs = Number(k.split(":")[2]);
44	    const { endMs } = JSON.parse(raw) as Hold;
45	    if (startMs < toMs && endMs > fromMs) out.push({ startMs, endMs });
46	  });
47	  return out;
48	}
49	
50	// ---------- Calendar events (Redis pub/sub → SSE) ----------
51	
52	export const calendarChannel = (businessId: string) => `calendar:${businessId}`;
53	
54	export async function publishCalendar(businessId: string, event: object): Promise<void> {
55	  await redis().publish(calendarChannel(businessId), JSON.stringify(event));
56	}
57	
58	// ---------- Availability ----------
59	
60	async function dayWindowFor(
61	  businessId: string,
62	  staffId: string,
63	  dateISO: string,
64	): Promise<{ open: string; close: string } | null> {
65	  const weekday = isoWeekday(dateISO);
66	  const [override] = await db
67	    .select()
68	    .from(s.staffHours)
69	    .where(and(eq(s.staffHours.staffId, staffId), eq(s.staffHours.weekday, weekday)));
70	  if (override) return { open: override.startTime, close: override.endTime };
71	  const [base] = await db
72	    .select()
73	    .from(s.businessHours)
74	    .where(and(eq(s.businessHours.businessId, businessId), eq(s.businessHours.weekday, weekday)));
75	  return base ? { open: base.openTime, close: base.closeTime } : null;
76	}
77	
78	export async function getAvailability(opts: {
79	  businessId: string;
80	  timeZone: string;
81	  staffId: string;
82	  serviceId: string;
83	  dateISO: string;
84	}): Promise<Range[]> {
85	  const { businessId, timeZone, staffId, serviceId, dateISO } = opts;
86	  const [service] = await db
87	    .select()
88	    .from(s.services)
89	    .where(and(eq(s.services.id, serviceId), eq(s.services.businessId, businessId)));
90	  if (!service?.isActive) return [];
91	
92	  const window = await dayWindowFor(businessId, staffId, dateISO);
93	  if (!window) return [];
94	
95	  const dayStart = localTimeToUtc(dateISO, "00:00", timeZone);
96	  const dayEnd = dayStart + 36 * 3600_000; // generous bound; window trims precisely
97	  const busyRows = await db
98	    .select({ startAt: s.bookings.startAt, endAt: s.bookings.endAt })
99	    .from(s.bookings)
100	    .where(
101	      and(
102	        eq(s.bookings.staffId, staffId),
103	        eq(s.bookings.status, "confirmed"),
104	        gte(s.bookings.endAt, new Date(dayStart)),
105	        lt(s.bookings.startAt, new Date(dayEnd)),
106	      ),
107	    );
108	  const busy = busyRows.map((b) => ({ startMs: b.startAt.getTime(), endMs: b.endAt.getTime() }));
109	  const holds = await listHolds(staffId, dayStart, dayEnd);
110	
111	  return slotsForDay({
112	    dateISO,
113	    timeZone,
114	    window,
115	    durationMin: service.durationMin,
116	    busy,
117	    holds,
118	    notBeforeMs: Date.now(),
119	  });
120	}
121	
122	// ---------- Booking creation ----------
123	
124	export type BookResult =
125	  | { ok: true; bookingId: string }
126	  | { ok: false; error: "hold_expired" | "slot_taken" };
127	
128	export async function createBooking(opts: {
129	  businessId: string;
130	  staffId: string;
131	  serviceId: string;
132	  slot: Range;
133	  holdToken: string;
134	  client: { name: string; phone: string };
135	}): Promise<BookResult> {
136	  const { businessId, staffId, serviceId, slot, holdToken, client } = opts;
137	
138	  // The hold must still be alive and belong to this caller.
139	  const raw = await redis().get(holdKey(staffId, slot.startMs));
140	  if (!raw || (JSON.parse(raw) as Hold).token !== holdToken) {
141	    return { ok: false, error: "hold_expired" };
142	  }
143	
144	  const [service] = await db
145	    .select()
146	    .from(s.services)
147	    .where(and(eq(s.services.id, serviceId), eq(s.services.businessId, businessId)));
148	  if (!service) return { ok: false, error: "slot_taken" };
149	
150	  // Upsert client by (business, phone)
151	  const [existing] = await db
152	    .select()
153	    .from(s.clients)
154	    .where(and(eq(s.clients.businessId, businessId), eq(s.clients.phone, client.phone)));
155	  const clientRow =
156	    existing ??
157	    (await db
158	      .insert(s.clients)
159	      .values({ businessId, name: client.name, phone: client.phone })
160	      .returning())[0];
161	
162	  try {
163	    // Booking, audit trail and outbound messages commit together: a client can
164	    // never end up with a confirmation for a booking that was rolled back.
165	    const bookingId = await db.transaction(async (tx) => {
166	      const [booking] = await tx
167	        .insert(s.bookings)
168	        .values({
169	          businessId,
170	          staffId,
171	          serviceId,
172	          clientId: clientRow.id,
173	          startAt: new Date(slot.startMs),
174	          endAt: new Date(slot.endMs),
175	          status: "confirmed",
176	          priceKzt: service.priceKzt,
177	        })
178	        .returning();
179	
180	      await tx.insert(s.auditLog).values({
181	        businessId,
182	        action: "booking.create",
183	        entity: "booking",
184	        entityId: booking.id,
185	        meta: { staffId, serviceId, startAt: new Date(slot.startMs).toISOString() },
186	      });
187	
188	      await enqueue(tx, {
189	        businessId,
190	        topic: "booking.confirmed",
191	        payload: { bookingId: booking.id },
192	        dedupeKey: `booking.confirmed:${booking.id}`,
193	      });
194	
195	      // Reminder the day before; retired automatically if the booking is
196	      // cancelled before the worker gets to it.
197	      const remindAt = new Date(slot.startMs - 24 * 3600_000);
198	      if (remindAt.getTime() > Date.now()) {
199	        await enqueue(tx, {
200	          businessId,
201	          topic: "booking.reminder",
202	          payload: { bookingId: booking.id },
203	          dedupeKey: `booking.reminder:${booking.id}`,
204	          availableAt: remindAt,
205	        });
206	      }
207	
208	      return booking.id;
209	    });
210	
211	    await redis().del(holdKey(staffId, slot.startMs));
212	    await publishCalendar(businessId, { type: "booking.created", bookingId });
213	    return { ok: true, bookingId };
