cat > /tmp/notecheck.ts <<'EOF'
import { z } from "zod";
const note = z.string().trim().max(500).nullish().transform((v) => v || null);
const cases: [string, unknown][] = [
  ["undefined", undefined],
  ["null", null],
  ["empty", ""],
  ["whitespace", "   \n\t "],
  ["trim", "  hi  "],
  ["newlines kept", "line1\n  line2\n"],
  ["500 ok", "a".repeat(500)],
  ["501 fail", "a".repeat(501)],
  ["500 + spaces ok", " " + "a".repeat(500) + " "],
];
for (const [name, v] of cases) {
  const r = note.safeParse(v);
  console.log(name.padEnd(18), r.success ? JSON.stringify(r.data) : "REJECT");
}
EOF
cp /tmp/notecheck.ts ./.notecheck.tmp.ts && pnpm exec tsx ./.notecheck.tmp.ts; rm -f ./.notecheck.tmp.ts /tmp/notecheck.ts
echo "--- tsc"; pnpm exec tsc --noEmit 2>&1 | tail -20; echo "tsc exit ${PIPESTATUS[0]}"
echo "--- lint"; pnpm exec eslint src/app/admin/page.tsx "src/app/[slug]/wizard.tsx" src/lib/booking.ts "src/app/api/public/[slug]/book/route.ts" 2>&1 | tail -20
echo "--- unit"; pnpm test 2>&1 | tail -15
